export const mattressVariantNames={thin:'薄款绗缝垫',padded:'加厚床褥垫',foam:'乳胶 / 海绵垫'};
export function mattressVariant(v={}){return v.mattressVariant||'thin'}
const structures={
  thin:{zh:'仅1张薄款绗缝软床垫：约1～2厘米轻薄夹棉、细浅菱格绗缝、窄平包边，平铺在承托床垫上，柔软可轻掀一角。无下垂床裙、松紧侧围或厚实立体床垫墙。',prompt:'Exactly ONE THIN QUILTED MATTRESS PAD, a loose-lay textile bed pad with approximately 1-2 cm shallow compressible batting, fine shallow diamond quilting and narrow flat sewn binding. Rest it flush on top of a neutral supporting mattress; its own thickness is ONLY the thin quilted pad above that support. No hanging sides, fitted elastic skirt, thick upright mattress wall, spring mattress or separate bed sheet.'},
  padded:{zh:'仅1张加厚软床褥垫：约4～6厘米可压缩柔软填充，宽方格绗缝、格内柔和隆起、缝处压低、圆润窄包边，平铺承托，局部翻角自然受重力。不是硬床垫、薄床笠或被芯。',prompt:'Exactly ONE THICK SOFT MATTRESS PAD / BED RUG, a loose-lay padded textile topper with approximately 4-6 cm compressible soft loft, broad square tack quilting, gently domed compartments with depressed stitches, rounded narrow bound edges and natural supported weight. Keep it atop the support with NO hanging quilt skirt, elastic fitted-sheet wrap, hard upright spring-mattress wall or separate bedsheet. Its loft belongs to the pad itself, not the supporting mattress.'},
  foam:{zh:'仅1张乳胶或海绵结构垫：约6～9厘米均匀低矮立体芯层，布套包覆顶面、短侧围和底面，窄缝包边，浅波浪压线可见。保持支撑形态，不捏造品牌、内部成分、剖面或弹簧。',prompt:'Exactly ONE MODEST-HEIGHT FOAM / LATEX STYLE MATTRESS TOPPER, approximately 6-9 cm uniform coherent supportive volume under a continuous textile shell, short upright sidewall, softly rounded supportive corners, restrained shallow wavy shell stitching and narrow upper/lower bound seams. Keep it flat on a neutral bare bed platform. Never depict an 18-30 cm spring mattress, loose quilt batting chambers, fitted-sheet elastic skirt or hanging fabric. Do not invent internal composition, latex purity, cutaway, springs or exposed foam.'}
};
export function mattressProductPrompt(v,zh=false){const item=structures[mattressVariant(v)];if(!item)return '';return (zh?item.zh:item.prompt)+(zh?'面料质感只改变外壳织纹、绒毛和光泽，不改变选定的薄厚及结构。花型属于垫子本身，不另铺床单。床头配拍2只装有枕芯的配套枕套，摆放可整齐或轻微错落；全景必须看见两只，特写可自然出画。不增加被子、毛毯或第二张垫子。':' CONSTRUCTION PRIORITY: selected subtype controls thickness, padding, flexibility, quilting and sidewall. Surface texture changes only the shell weave, nap and sheen, NEVER its selected construction. Uploaded print belongs to this pad shell itself, NOT to an extra sheet. Include exactly TWO matching pillowcase-covered sleeping pillows at the head, neatly aligned or naturally slightly tilted; both visible in full bed views, naturally outside detail crops. No duvet, blanket or second topper.')}
export function mattressDirection(v,angle,common={}){
  const kind=mattressVariant(v),thin=kind==='thin',foam=kind==='foam',edge=foam?'short upright coherent sidewall with upper/lower seams':thin?'thin softly compressible quilted edge and narrow flat binding':'soft compressible padded edge and rounded narrow binding',surface=foam?'restrained shallow wavy shell stitches':thin?'fine shallow diamond quilting':'broad square quilting, stitch compression and softly domed loft';
  const spec=structures[kind];if(!spec)return null;
  if(common.prompt)return {...common,prompt:common.prompt+' SELECTED MATTRESS PAD: '+spec.prompt+' Show '+edge+' and '+surface+'. Never mistake the supporting mattress thickness for this pad.',zh:common.zh+' '+(foam?'保持低矮立体芯层。':thin?'保持薄软夹棉，不画厚床垫。':'保持柔软加厚床褥，不画硬床垫。')};
  const views={
    detail:{name:'绗缝面料特写',zh:'中近景拍垫子自身织纹、印花和真实压线，细节占50%～65%，周围连续垫面可见。'+(foam?'压线浅，不画蓬松填充格。':thin?'细浅菱格，轻薄夹棉。':'宽方格，缝处压低，格内柔和隆起。'),prompt:'MATTRESS PAD TEXTILE DETAIL: contextual 30-45-degree medium-close photo, 85-100 mm equivalent, actual pad shell weave/print and '+surface+', connected surrounding top visible. Detail 50-65% with editing margin. No detached swatch, oversized fibers or different pad construction.'},
    low:{name:'垫层厚度展示',zh:'床尾低机位近水平展示完整垫子和边缘厚度，产品占60%～70%，明确区分垫层与下方承托床垫。',prompt:'MATTRESS PAD THICKNESS: low foot-end near-horizontal camera at PAD edge height, 40-55 mm lens, entire pad with margins, 60-70% coverage. Show '+edge+' ABOVE the distinct neutral support. Thickness belongs to the selected pad; do not substitute the supporting mattress or bed frame height.'},
    reverse:foam?{name:'底面展示',zh:'同一张低矮立体垫稳稳立在长边上，完整底面朝镜头，短侧围连续，不折叠、不卷起、不拆开。',prompt:'FOAM PAD UNDERSIDE DISPLAY: SAME modest-height topper resting stably upright ON ITS LONG EDGE, actual bottom face toward camera, full rectangle 60-70% with margins. Continuous short sidewall and binding. Never fold, roll, float, dismantle or expose an invented core.'}:{name:'翻角看底面',zh:'仅轻掀靠镜头的一小段真实垫角，露出底面，其余大部分平铺承托。'+(thin?'薄软角部小幅弧形，不形成厚翻被。':'柔软加厚角部宽弧弯曲，缝边自然压缩。'),prompt:'MATTRESS PAD CORNER UNDERSIDE: medium-close foot-corner oblique photo; lift ONLY a SMALL actual near corner into one '+(thin?'shallow soft natural curve':'broad rounded weight-settled compressible curve')+' to reveal its real underside and connected sewn edge, while at least TWO THIRDS remain flat and supported. Main corner and contact shadows visible, detail 50-65% with margins. No whole pad upright, broad head-end duvet turnover, triangular floating flap, detached fabric strip or hard slab.'},
    foot:{name:'床尾包边展示',zh:'略俯拍垫子下半部和完整床尾宽度，两个前角均留在画内，垫面、垫层和包边连续，无下垂裙边。',prompt:'MATTRESS PAD FOOT EDGE: slightly elevated 30-45-degree photo of LOWER HALF and FULL foot width with BOTH actual front corners and usable margins. Show connected '+surface+', '+edge+'. No clipped corner, hanging pad skirt or exposed separate sheet.'},
    pillowclose:{name:'床垫边角特写',zh:'中近景拍一个真实圆角、相连垫面和包边，细节占50%～65%；薄垫柔软、床褥可压缩、海绵垫保持短侧围。',prompt:'MATTRESS PAD CORNER CLOSE-UP: one real rounded sewn corner, surrounding connected top with '+surface+' and '+edge+', 30-45-degree contextual camera, 70-85 mm lens, detail 50-65%. No pillowcase, invented zipper, fitted elastic corner pocket or hanging sheet.'},
    drape:{name:foam?'短侧围展示':'长边包边展示',zh:'沿垫子至少半条长边中近景拍摄，垫面与边缘连续，主体受床面承托；不生成布料垂边。',prompt:'MATTRESS PAD SIDE EDGE DISPLAY: contextual view along at least HALF long side, camera near actual pad edge height. Connected top and '+edge+' rest flush on neutral support. Preserve selected padding and quilting. NO hanging cloth, bed skirt, duvet or fitted sheet.'}
  };
  return views[angle]||null;
}
